mapper.insert:
INSERT INTO PRODUCTITEM (PINUM,PINAME,PIISBN,PIPRICE,PIAMOUNT,PISUMPRICE,PIUNITCOST,PFNUM,picategory) SELECT productItem_seq.NEXTVAL, A.PINAME,A.PIISBN,A.PIPRICE,A.PIAMOUNT,A.PISUMPRICE,A.PIUNITCOST, productForm_seq.currVal,A.picategory FROM (
SELECT #{item.piname} AS piname, #{item.piisbn} AS piisbn, #{item.piprice} AS piprice, #{item.piamount} AS piamount, #{item.pisumprice} AS pisumprice, #{item.piunitCost} AS piunitCost, #{item.picategory} AS picategory FROM DUAL
) A
